//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils_detect.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stockSearch.js");
scwin.vScrenID = "ULDSTF35603.xml";
scwin.svrGubun = js_svrGubun; //DR전환시
scwin.gWorkDD;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    dts_IndCd.DataID = "/AdminAndDlstedDetection.do?method=getComboList&For=IR&outputMessageId=AADD_OUT_COMBO";
    dts_IndCd.Reset();
};


//거래량 요건  검색 
scwin.fn_list_sync = function() {
    if ($c.stf.getObjectValue(edt_BASE_DD) > $c.ut.cGetToday("yyyymmdd")) {
        $c.win.alert("현재일자보다 기준일자가 이후일 수 없습니다.");
        edt_BASE_DD.focus();
        return;
    }
    if ($c.stf.getObjectValue(rdo_TERM) < 1) {
        $c.win.alert("기준월을 선택하세요.");
        rdo_TERM.focus();
        return;
    }
    btn_Search.setDisabled(true);
    btn_Search.src = "../img/btn_select_d.gif";
    if (scwin.svrGubun == "dr") {
        //DR일 경우 2011.01.28
        $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
        $c.stf.setObjectValue(txb_TR_STATE_CD, "-");
        $c.stf.setObjectValue(txb_ATS_STATE_CD, "-");
    } else {
        scwin.fn_set_trstatcd();
    }
    //var url = "/AdminAndDlstedDetection.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01+"&method=getTransList&For=TTA&inputMessageId=AADD_IN&outputMessageId=AADD_OUT_TTA";
    //url+= "&ISUR_CD=" + getObjectValue(txb_ISU_CD);
    //url+= "&BASE_DT=" + getObjectValue(edt_BASE_DD);
    //url+= "&IND_CD=" + getObjectValue(cmb_IND_DD);
    //url+= "&TERM=" + getObjectValue(rdo_TERM);
    scwin.fn_WorkDD();
    var IND_CD = $c.stf.getObjectValue(cmb_IND_DD);
    var ISU_CD = $c.stf.getObjectValue(txb_ISU_CD);
    var BASE_DD = $c.stf.getObjectValue(edt_BASE_DD);
    var TERM = "-" + $c.stf.getObjectValue(rdo_TERM);
    if (ISU_CD == "") ISU_CD = "%";
    url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=AADD_OUT_TTA" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_transamt.list" + "&{P}param01=" + BASE_DD + // 기준일
        "&{P}param02=" + scwin.gWorkDD + "&{P}param03=" + scwin.gWorkDD + "&{P}param04=" + scwin.gWorkDD + "&{P}param05=" + IND_CD + "&{P}param06=" + IND_CD + "&{P}param07=" + ISU_CD + "&{P}param08=" + scwin.gWorkDD + "&{P}param09=" + TERM + "&{P}param10=" + scwin.gWorkDD + "&{P}param11=" + BASE_DD + // 기준일
        "&{P}param12=" + TERM + "&{P}param13=" + BASE_DD + // 기준일
        "&{P}param14=" + BASE_DD + // 기준일
        "&{P}param15=" + TERM + "&{P}param16=" + BASE_DD + // 기준일
        "&{P}param17=" + BASE_DD + // 기준일
        "&{P}param18=" + TERM + "&{P}param19=" + BASE_DD; // 기준일

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List); // 그리드명을 표기

};

//종류주식 거래량 요건  검색 
scwin.fn_list_sync_2 = function() {
    if ($c.stf.getObjectValue(edt_BASE_DD) > $c.ut.cGetToday("yyyymmdd")) {
        $c.win.alert("현재일자보다 기준일자가 이후일 수 없습니다.");
        edt_BASE_DD.focus();
        return;
    }
    if ($c.stf.getObjectValue(rdo_TERM) < 1) {
        $c.win.alert("기준월을 선택하세요.");
        rdo_TERM.focus();
        return;
    }
    btn_Search.setDisabled(true);
    btn_Search.src = "../img/btn_select_d.gif";
    if (scwin.svrGubun == "dr") {
        //DR일 경우 2011.01.28
        $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
        $c.stf.setObjectValue(txb_TR_STATE_CD, "-");
        $c.stf.setObjectValue(txb_ATS_STATE_CD, "-");
    } else {
        scwin.fn_set_trstatcd();
    }
    /*
    var url = "/AdminAndDlstedDetection.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01
              +"&method=getTransList&For=KNTTA&inputMessageId=AADD_IN&outputMessageId=AADD_OUT_TTA";
    url+= "&ISUR_CD=" + getObjectValue(txb_ISU_CD);
    url+= "&BASE_DT=" + getObjectValue(edt_BASE_DD);
    url+= "&IND_CD=" + getObjectValue(cmb_IND_DD);
    url+= "&TERM=" + getObjectValue(rdo_TERM);
    */
    scwin.fn_WorkDD();
    var IND_CD = $c.stf.getObjectValue(cmb_IND_DD);
    var ISU_CD = $c.stf.getObjectValue(txb_ISU_CD);
    var BASE_DD = $c.stf.getObjectValue(edt_BASE_DD);
    var TERM = "-" + $c.stf.getObjectValue(rdo_TERM);
    if (ISU_CD == "") ISU_CD = "%";
    url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=AADD_OUT_TTA" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_kntransamt.list" + "&{P}param01=" + BASE_DD + // 기준일
        "&{P}param02=" + scwin.gWorkDD + "&{P}param03=" + scwin.gWorkDD + "&{P}param04=" + scwin.gWorkDD + "&{P}param05=" + IND_CD + "&{P}param06=" + IND_CD + "&{P}param07=" + ISU_CD + "&{P}param08=" + scwin.gWorkDD + "&{P}param09=" + TERM + "&{P}param10=" + scwin.gWorkDD + "&{P}param11=" + BASE_DD + // 기준일
        "&{P}param12=" + TERM + "&{P}param13=" + BASE_DD + // 기준일
        "&{P}param14=" + BASE_DD + // 기준일
        "&{P}param15=" + TERM + "&{P}param16=" + BASE_DD + // 기준일
        "&{P}param17=" + BASE_DD + // 기준일
        "&{P}param18=" + TERM + "&{P}param19=" + BASE_DD; // 기준일

    dts_List2.DataID = encodeURI(url);
    dts_List2.reset();
    $c.cm.ShowWin(grd_List2); // 그리드명을 표기

};
scwin.fn_set_trstatcd = function() {
    $c.stf.setObjectValue(txb_TR_STATE_CD, $c.ud.fn_get_divtrstatcd(dts_TR_STATE_CD, $c.stf.getObjectValue(edt_BASE_DD), "1"));
    $c.stf.setObjectValue(txb_ATS_STATE_CD, $c.ud.fn_get_divtrstatcd(dts_TR_STATE_CD, $c.stf.getObjectValue(edt_BASE_DD), "3"));
};
scwin.fn_WorkDD = function() {
    var url2 = "/listingCommon.do?method=listGeneral" + "&outputMessageId=MKT_HCALND_DD_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_workday.select" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD);
    dts_WorkDD.DataID = encodeURI(url2);
    dts_WorkDD.reset();
    scwin.gWorkDD = dts_WorkDD.getCellData(1, "CALND_DD");
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List); //데이터 로딩중닫기 및 조회없음 처리
    btn_Search.setDisabled(false);
    btn_Search.src = "../img/btn_select.gif";
};
scwin.dts_List_OnLoadError = function() {
    //alert_error(dts_List);
    $c.win.alert("해당 일자의 데이터가 존재하지 않습니다.");
    $c.cm.CloseWin(0, grd_List); //데이터 로딩중닫기 및 조회없음 처리
    btn_Search.setDisabled(false);
    btn_Search.src = "../img/btn_select.gif";
};
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List2); //데이터 로딩중닫기 및 조회없음 처리		
    btn_Search.setDisabled(false);
    btn_Search.src = "../img/btn_select.gif";
};
scwin.dts_List2_OnLoadError = function() {
    //alert_error(dts_List);
    $c.win.alert("해당 일자의 데이터가 존재하지 않습니다.");
    $c.cm.CloseWin(0, grd_List2); //데이터 로딩중닫기 및 조회없음 처리
    btn_Search.setDisabled(false);
    btn_Search.src = "../img/btn_select.gif";
};
scwin.img_BASE_DD_onclick = function() {
    popUpCalendar2(edt_BASE_DD);
};
scwin.btn_Excel_onclick = function() {
    var tIndex = MxTab_1.getSelectedTabIndex();
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (tIndex == 1) {
        $c.data.downloadGridViewExcel(grd_List, "거래현황 -거래량요건 목록", "", "8");
    } else if (tIndex == 2) {
        $c.data.downloadGridViewExcel(grd_List2, "거래현황 -종류주식 거래량요건 목록", "", "8");
    }
};
scwin.btn_Search_onclick = function() {
    var tIndex = MxTab_1.getSelectedTabIndex();
    if (tIndex == 1) {
        scwin.fn_list_sync();
    } else if (tIndex == 2) {
        scwin.fn_list_sync_2();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISU_CD_onkeyup = function() {
    if (txb_ISU_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISU_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISU_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISU_CD.getValue() == "") {
        txb_ISU_NM.setValue("");
    }
};
scwin.img_ISU_NM_onclick = function() {
    $c.stockSearch.JongmokSearch(txb_ISU_CD, txb_ISU_NM, SECUGRP_ID_ST, js_market, "A");
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxTab_1_OnSelChanged = async function(nIndex) {
    var eCnt = 0; // 각 dataset 별 표시 count
    var tIndex = MxTab_1.getSelectedTabIndex();
    //alert(tIndex);
    if (tIndex == 1) {
        eCnt = dts_List.getTotalRow();
    } else if (tIndex == 2) {
        eCnt = dts_List2.getTotalRow();
    }
    $c.stf.FillGridHeaderTotalCnt(eCnt, panel_page);

    //tab을 선택 시 기존 그리드의 '조회결과 없음'표시를 닫는다.
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
};
scwin.gform_onload = function() {
    MxTab_1.setSelectedTabIndex(1);
    scwin.fn_SetCode();

    //오늘날짜로 초기화시킨다.
    var today = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(edt_BASE_DD, today);
    rdo_TERM.setValue(Number(eval(today.substring(4, 6)) % 6 - 1));
    if (rdo_TERM.getValue() < 1) {
        rdo_TERM.setValue('5');
    }
    $c.cm.fn_com_isur(txb_ISU_CD, txb_ISU_NM);
    Grd_com_isur.style.zIndex = 30;
    if (scwin.svrGubun == "dr") {
        $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
        $c.stf.setObjectValue(txb_TR_STATE_CD, "-");
        $c.stf.setObjectValue(txb_ATS_STATE_CD, "-");
    } else {
        scwin.fn_set_trstatcd();
    }

    //round처리
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
};
scwin.dts_TR_STATE_CD_OnLoadError = function() {
    $c.stf.alert_error(dts_TR_STATE_CD);
};
scwin.dts_WorkDD_OnLoadError = function() {
    $c.stf.alert_error(dts_WorkDD);
};
